// Part of React Advanced Odontogram - https://github.com/ZoliQua/React-Advanced-Odontogram
// Created by Zoltan Dul (https://github.com/ZoliQua) 2025-2026
//
// Bundled Unicode font for the PDF report. jsPDF's built-in Helvetica uses
// WinAnsi encoding, so it cannot render Hungarian double-acute accents (ő/ű) or
// Cyrillic (ru), producing garbled output. This embeds a tight subset of Roboto
// (Apache-2.0) — Basic Latin, Latin-1, Latin Extended-A, the Romanian
// comma-below letters, Cyrillic (U+0400–045F + ґ/ѐ), and the punctuation the
// report uses (en/em dash, curly quotes, bullet, ellipsis, €, minus) — covering
// every Latin/Cyrillic UI language (hu, en, de, es, it, sk, pl, ru, pt-br, fr)
// in ~27 KB per weight (GSUB/GPOS/hinting stripped). Arabic (ar) and Chinese
// (zh) have their own shaped/CJK fonts.
//
// Base64-embedded (not fetched) so the export works fully offline, like the
// ?raw-inlined tooth-template SVGs. Regular + Bold only; italic/bold-italic are
// mapped to those upright faces (jsPDF cannot synthesize a slant for an embedded
// TTF, and a missing style would throw). Subset built with pyftsubset from
// Roboto-{Regular,Bold}.ttf.

/** jsPDF surface needed to register an embedded font (subset of jsPDF's API). */
export interface FontRegistrable {
  addFileToVFS?: (fileName: string, data: string) => void;
  addFont?: (fileName: string, fontName: string, fontStyle: string) => void;
}

/** The font family name to pass to `doc.setFont(PDF_FONT_FAMILY, style)`. */
export const PDF_FONT_FAMILY = "Roboto";

const ROBOTO_REGULAR_B64 = "";
const ROBOTO_BOLD_B64 = "";

const registeredFor: WeakSet<object> = new WeakSet();

/**
 * Register the bundled Roboto subset on a jsPDF document so `setFont("Roboto",
 * style)` renders Unicode text. No-op (returns false) when the doc lacks the
 * VFS/addFont API — e.g. the fake `PdfDocLike` used in unit tests — so the pure
 * assembler stays testable without a real jsPDF. Idempotent per document.
 */
export function registerRobotoFont(doc: FontRegistrable): boolean {
  if (typeof doc.addFileToVFS !== "function" || typeof doc.addFont !== "function") return false;
  if (registeredFor.has(doc as object)) return true;
  doc.addFileToVFS("Roboto-Regular.ttf", ROBOTO_REGULAR_B64);
  doc.addFileToVFS("Roboto-Bold.ttf", ROBOTO_BOLD_B64);
  doc.addFont("Roboto-Regular.ttf", PDF_FONT_FAMILY, "normal");
  doc.addFont("Roboto-Bold.ttf", PDF_FONT_FAMILY, "bold");
  // No true italic face in the subset — map italic/bold-italic onto the upright
  // regular/bold files so setFont(..., "italic") never throws (loses the slant).
  doc.addFont("Roboto-Regular.ttf", PDF_FONT_FAMILY, "italic");
  doc.addFont("Roboto-Bold.ttf", PDF_FONT_FAMILY, "bolditalic");
  registeredFor.add(doc as object);
  return true;
}
